"use strict";

  function firmCard(f){return `<article class="result-card"><div><span class="owner-label">Примерен фирмен профил</span><h3>${esc(f.name)}</h3><p>${esc(f.description)}</p><div class="result-meta"><span class="badge badge-blue">Пример за интерфейса</span><span>${esc(f.category)}</span><span>${esc(f.city)}</span>${f.expanded?`<span class="badge badge-blue">Разширен профил</span>`:""}${f.admin?`<span class="badge badge-dark">Администраторски сценарий</span>`:""}</div></div><div class="result-actions"><button class="button button-soft" type="button" data-route="firm/${f.id}">Виж примерния профил</button></div></article>`}
  function renderFirms(){main.innerHTML=pageIntro("Постоянни профили","Фирми","Постоянният фирмен профил е различен от временната обява.",button("Добави фирма","firm-form","button button-primary"))+`<section class="section"><div class="shell"><div class="notice notice-info"><strong>Примерни записи за преглед</strong>Офлайн R1 не зарежда production фирмите. Картите по-долу са fixtures за профил, филтри, роли и expanded UX.</div><div class="toolbar mt-16"><input class="toolbar-search" id="firm-search" type="search" placeholder="Търси фирма или категория"><div class="segmented"><button class="active" data-firm-category="all">Всички</button><button data-firm-category="Строителство и ремонти">Ремонти</button><button data-firm-category="Автомобили">Автомобили</button><button data-firm-category="Заведения">Заведения</button></div></div><div id="firm-results">${stateGate(`<div class="result-list">${[...D.firms].sort((a,b)=>Number(b.admin)-Number(a.admin)).map(firmCard).join("")}</div>`,"Все още няма фирми.")}</div></div></section>`}
  function renderFirmDetail(id){const f=D.firms.find(x=>x.id===id);if(!f)return renderNotFound();main.innerHTML=pageIntro("Примерен фирмен профил",f.name,f.category,`<button class="button button-primary" type="button" data-action="call" data-phone="${esc(f.phone)}">Обади се</button>`+`<button class="button button-soft" type="button" data-share="firm/${f.id}" data-share-title="${esc(f.name)}">Сподели</button>`)+`<section class="section"><div class="shell"><div class="notice notice-info"><strong>Прототипен запис</strong>Контактите и съдържанието на тази карта са за преглед на интерфейса и не се представят като текущ публичен фирмен запис.</div><div class="detail-layout mt-16"><div class="detail-main">${crumb([["Фирми","firms"],[f.name,""]])}<div class="detail-title"><div class="flex"><span class="badge badge-blue">Пример за интерфейса</span>${f.expanded?`<span class="badge badge-blue">Разширен профил</span>`:""}</div><h1>${esc(f.name)}</h1><p>${esc(f.description)}</p></div>${f.expanded?`<div class="detail-block"><h2>Услуги</h2><div class="tag-row">${(f.services||[]).map(x=>`<span class="badge badge-blue">${esc(x)}</span>`).join("")}</div></div><div class="detail-block"><h2>Район на работа</h2><p>${esc(f.area||f.city)}</p></div>`:""}<div class="detail-block"><h2>Галерия</h2><div class="notice notice-info"><strong>Медията е изключена в офлайн R1</strong>В реалния профил тук се показват само одобрените снимки на съответната фирма. Не измисляме шест фалшиви снимки само за запълване.</div></div>${f.expanded?`<div class="detail-block"><h2>Преди и след</h2><div class="grid grid-2"><div class="notice"><strong>Преди</strong>Целевото място за одобрена снимка преди ремонта.</div><div class="notice notice-ok"><strong>След</strong>Целевото място за одобрена снимка след ремонта.</div></div><p class="muted small">Секцията е част от целевия expanded profile, но истинският editor/write flow остава отделна следваща защитена задача.</p></div>`:""}<div class="detail-block"><h2>Контакти и работно време</h2><div class="facts"><div class="fact"><span>Телефон</span><strong>${esc(f.phone)}</strong></div><div class="fact"><span>Адрес</span><strong>${esc(f.address||"Не е посочен")}</strong></div><div class="fact"><span>Работно време</span><strong>${esc(f.hours||"Не е посочено")}</strong></div>${f.website?`<div class="fact"><span>Сайт</span><strong>${esc(f.website)}</strong></div>`:""}</div></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" type="button" data-action="call" data-phone="${esc(f.phone)}">Обади се</button><button class="button button-outline" type="button" data-route="offer-request?firm=${f.id}">Поискай оферта — целеви прототип</button>${f.website?`<button class="button button-outline" type="button" data-action="website" data-url="https://${esc(f.website)}">Сайт</button>`:""}<button class="button button-outline" type="button" data-share="firm/${f.id}" data-share-title="${esc(f.name)}">Сподели</button><button class="button button-outline" type="button" data-route="report?target=${encodeURIComponent(f.name)}&owner=firm">Докладвай</button><button class="button button-soft" type="button" data-route="firm-form?edit=${f.id}">Редактирай (прототип)</button></div></aside></div></div></section>`}
  function renderFirmForm(){const r=routeInfo(),editId=r.params.get("edit"),f=editId?D.firms.find(x=>x.id===editId):null;const submitLabel=isAdmin()?(f?"Запази и публикувай":"Публикувай фирмата"):(f?"Изпрати редакцията":"Изпрати за преглед");const galleryText=isAdmin()?"Администраторският профил не използва обикновения лимит за снимки":"До 6 снимки за обикновена фирма";main.innerHTML=pageIntro("Фирмен профил",f?"Редактирай фирма":"Добави фирма",f?"Последната одобрена публична версия остава видима, докато редакцията чака преглед.":"Създай основен постоянен профил. Обикновеният потребител изпраща за преглед.")+`<section class="section"><div class="shell form-wrap"><div class="form-card">${!isAdmin()?`<div class="notice notice-info"><strong>${isModerator()?"Модератор — собствена фирма":"Публикуване след преглед"}</strong>${isModerator()?"Собствената фирма на модератор следва нормалния потребителски flow — без директно публикуване и без Admin права.":"Новата фирма не става публична преди одобрение."}</div>`:`<div class="notice notice-ok"><strong>Администраторски режим</strong>Директно публикуване и защитен expanded access според съществуващите правила.</div>`}<form class="form-grid proto-form mt-16" data-form="firm" data-edit-id="${esc(editId||"")}">${field("Име на фирмата","name",{required:true,min:2,value:f?.name||""})}${selectField("Категория","category",["Строителство и ремонти","Автомобили","Професионални услуги","Заведения","Красота","Дом и градина","Друго"],f?.category||"",{required:true})}${field("Телефон","phone",{required:true,type:"tel",value:f?.phone||""})}${field("Град (по желание)","city",{value:f?.city||"Лом"})}${field("Адрес (по желание)","address",{value:f?.address||""})}${field("Работно време (по желание)","hours",{value:f?.hours||""})}${field("Описание","description",{textarea:true,required:true,min:20,full:true,value:f?.description||"",placeholder:f?.category==="Заведения"?"Опиши типа заведение, кухнята, услугите и какво е полезно клиентът да знае":"Опиши с какво се занимава фирмата, основните услуги и какво е полезно клиентът да знае"})}<div class="field field-full"><label>Лого (по желание)</label><div class="photo-drop"><input type="file" name="logo" accept="image/jpeg,image/png,image/webp"><strong>1 лого</strong><br><small>JPG, PNG или WebP. Не се качва реално.</small></div></div><div class="field field-full"><label>Снимки на обекти и услуги</label><div class="photo-drop"><input type="file" name="gallery" accept="image/jpeg,image/png,image/webp" multiple><strong>${esc(galleryText)}</strong></div></div>${isAdmin()?`<div class="form-section"><h3>Разширен профил — само за Admin управление на достъпа</h3><p class="muted">Достъпът не се включва сам от нормален потребител или модератор.</p>${field("Кратко представяне","short_intro",{textarea:true,full:true})}${field("Сайт","website",{type:"url",full:true})}${field("Услуги — по една на ред","services",{textarea:true,full:true})}${field("Район на работа","service_area",{textarea:true,full:true})}${field("Работно време — разширено","expanded_hours",{textarea:true,full:true})}<div class="grid grid-2"><label class="check-row"><input type="checkbox" name="show_intro"> Покажи представянето</label><label class="check-row"><input type="checkbox" name="show_site"> Покажи бутона „Сайт“</label><label class="check-row"><input type="checkbox" name="show_services"> Покажи услугите</label><label class="check-row"><input type="checkbox" name="show_area"> Покажи района</label><label class="check-row"><input type="checkbox" name="show_hours"> Покажи разширеното работно време</label></div></div>`:""}<div class="form-actions"><button class="button button-outline" type="button" data-route="firms">Отказ</button><button class="button button-primary" type="submit">${esc(submitLabel)}</button></div></form></div></div></section>`;bindFormUX()}
  function renderRestaurants(){const rows=D.firms.filter(x=>x.category==="Заведения");main.innerHTML=pageIntro("Открий в Лом","Заведения и храна","Това е специализиран изглед за откриване, а постоянният профил остава фирмен профил.",button("Виж всички фирми","firms"))+`<section class="section"><div class="shell"><div class="notice notice-info"><strong>Без втори каталог</strong>Заведението се съхранява като фирмен профил. Показаният R1 запис е пример за интерфейса, не текущ local business факт.</div><div class="result-list mt-16">${rows.map(firmCard).join("")}</div></div></section>`}

  function shopCard(s){return `<article class="result-card"><div><span class="owner-label">Примерен магазин</span><h3>${esc(s.name)}</h3><p>${esc(s.category)} · ${esc(s.address)}</p><div class="tag-row"><span class="badge badge-blue">Пример за интерфейса</span>${s.tags.map(t=>`<span class="badge">${esc(t)}</span>`).join("")}</div></div><div class="result-actions"><button class="button button-primary" data-action="call" data-phone="${esc(s.phone)}">Обади се</button><button class="button button-soft" data-route="shop/${s.id}">Детайли</button></div></article>`}
  function renderShops(){const cats=["Всички","Хранителни","Строителни","Техника","Мебели","Дрехи","Дом"];main.innerHTML=pageIntro("Открий в Лом","Магазини","Специализиран каталог с отделен поток за предложение на нов магазин.",button("Предложи магазин","shop-proposal","button button-primary"))+`<section class="section"><div class="shell"><div class="notice notice-info"><strong>Примерни записи</strong>R1 не зарежда production каталога за магазини. Данните по-долу са само за tabs, търсене, detail и proposal QA.</div><div class="toolbar mt-16"><input id="shop-search" class="toolbar-search" type="search" placeholder="Търси магазин, адрес или какво предлага"><div class="segmented">${cats.map((c,i)=>`<button class="${i===0?"active":""}" data-shop-category="${esc(c)}">${esc(c)}</button>`).join("")}</div></div><div id="shop-results">${stateGate(`<div class="result-list">${D.shops.map(shopCard).join("")}</div>`,"Все още няма одобрени магазини.")}</div></div></section>`}
  function renderShopDetail(id){const s=D.shops.find(x=>x.id===id);if(!s)return renderNotFound();main.innerHTML=pageIntro("Примерен магазин",s.name,s.category,`<button class="button button-primary" data-action="call" data-phone="${esc(s.phone)}">Обади се</button>`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Магазини","shops"],[s.name,""]])}<div class="notice notice-info"><strong>Пример за интерфейса</strong>Този запис не се представя като текущ реален магазин.</div><div class="detail-block"><h2>Информация</h2><div class="facts"><div class="fact"><span>Категория</span><strong>${esc(s.category)}</strong></div><div class="fact"><span>Адрес</span><strong>${esc(s.address)}</strong></div><div class="fact"><span>Работно време</span><strong>${esc(s.hours)}</strong></div><div class="fact"><span>Телефон</span><strong>${esc(s.phone)}</strong></div></div><div class="tag-row">${s.tags.map(t=>`<span class="badge badge-blue">${esc(t)}</span>`).join("")}</div></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" data-action="call" data-phone="${esc(s.phone)}">Обади се</button><button class="button button-outline" data-share="shop/${s.id}" data-share-title="${esc(s.name)}">Сподели</button><button class="button button-outline" data-route="report?target=${encodeURIComponent(s.name)}&owner=shop">Докладвай</button></div></aside></div></section>`}
  function renderShopProposal(){main.innerHTML=pageIntro("Магазини","Предложи магазин","Специализирана форма за каталогa на магазини; не се заменя с „Добави фирма“.")+`<section class="section"><div class="shell form-wrap"><div class="form-card"><div class="notice notice-info"><strong>Изисква вход</strong>Предложението се изпраща за проверка и не е публично веднага.</div><form class="form-grid proto-form mt-16" data-form="shop-proposal">${field("Име на магазина","name",{required:true,min:2})}${selectField("Категория","category",["Хранителни","Строителни","Техника","Мебели","Дрехи","Дом"],"",{required:true})}${field("Телефон","phone",{required:true,type:"tel"})}${field("Адрес","address",{required:true,min:3})}${field("Работно време","hours",{})}${field("Какво предлага","offer",{textarea:true,required:true,min:15,full:true,placeholder:"Кратко и конкретно описание"})}${field("Уточнения / тагове","tags",{full:true,placeholder:"напр. Бои, инструменти, санитария"})}${field("Източник / откъде знаеш","source",{textarea:true,full:true,placeholder:"По желание — сайт, табела, личен контакт"})}<div class="form-actions"><button class="button button-outline" type="button" data-route="shops">Отказ</button><button class="button button-primary" type="submit">Изпрати за проверка</button></div></form></div></div></section>`;bindFormUX()}

  function eventCard(e){return `<article class="result-card"><div><span class="owner-label">Примерно събитие</span><h3>${esc(e.title)}</h3><p>${esc(e.date)} · ${esc(e.time)} · ${esc(e.place)}</p><div class="result-meta"><span class="badge badge-blue">Пример за интерфейса</span></div></div><div class="result-actions"><button class="button button-soft" data-route="event/${e.id}">Виж примерния детайл</button></div></article>`}
  function renderEvents(){main.innerHTML=pageIntro("Открий в Лом","Събития","Публичният изглед показва одобрени текущи и предстоящи събития. Публична форма „Добави събитие“ не се измисля.",button("Попитай за събитие","ask?category=Събития","button button-primary"))+`<section class="section"><div class="shell"><div class="notice notice-info"><strong>Примерни записи за layout QA</strong>R1 не твърди, че тези събития предстоят реално в Лом. Реалният каталог се чете от Events owner-а. Няма фалшив бутон „Добави събитие“.</div><div class="mt-16">${stateGate(`<div class="result-list">${D.events.map(eventCard).join("")}</div>`,"В момента няма предстоящи одобрени събития.")}</div></div></section>`}
  function renderEventDetail(id){const e=D.events.find(x=>x.id===id);if(!e)return renderNotFound();main.innerHTML=pageIntro("Примерно събитие",e.title,`${e.date} · ${e.time} · ${e.place}`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Събития","events"],[e.title,""]])}<div class="notice notice-info"><strong>Пример за интерфейса</strong>Датата и мястото са fixture данни, не текуща публична програма.</div><div class="detail-block"><h2>За събитието</h2><p>${esc(e.description)}</p><div class="facts"><div class="fact"><span>Дата</span><strong>${esc(e.date)}</strong></div><div class="fact"><span>Час</span><strong>${esc(e.time)}</strong></div><div class="fact"><span>Място</span><strong>${esc(e.place)}</strong></div></div></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" data-share="event/${e.id}" data-share-title="${esc(e.title)}">Сподели</button><button class="button button-outline" data-route="ask?category=Събития&q=${encodeURIComponent(e.title)}">Попитай</button><button class="button button-outline" data-route="report?target=${encodeURIComponent(e.title)}&owner=event">Докладвай</button></div></aside></div></section>`}
